class Solution {
public:
    int countBalls(int lowLimit, int highLimit) {
        vector<int> cnt(46, 0);
        int best = 0;
        for (int x = lowLimit; x <= highLimit; x++) {
            int s = 0;
            for (int y = x; y; y /= 10) s += y % 10;
            best = max(best, ++cnt[s]);
        }
        return best;
    }
};

